/**
 * Cross-language parity: these vectors are generated by
 * tools/geo/test_geo_core.py from the Python reference implementation. If
 * this suite and the Python suite both pass, the app and the tooling agree.
 */
import { TripEngine, estimateTrip, formatDistance, formatEta, type TripRoute } from '../eta';
import { bearingDeg, decodePolyline, encodePolyline, haversineM, headingDelta, projectOntoRoute, type LngLat } from '../geo';

const fx = require('../../../../tools/geo/fixtures/geo_vectors.json');

describe('geo math (shared vectors)', () => {
  it('matches haversine distances', () => {
    for (const v of fx.haversine) {
      expect(haversineM(v.a, v.b)).toBeCloseTo(v.meters, 6);
    }
  });

  it('matches bearings', () => {
    for (const v of fx.bearing) {
      expect(bearingDeg(v.a, v.b)).toBeCloseTo(v.degrees, 6);
    }
  });

  it('encodes and decodes polyline6 identically', () => {
    expect(encodePolyline(fx.polyline.line)).toBe(fx.polyline.encoded6);
    decodePolyline(fx.polyline.encoded6).forEach((point, i) => {
      expect(point[0]).toBeCloseTo(fx.polyline.line[i][0], 6);
      expect(point[1]).toBeCloseTo(fx.polyline.line[i][1], 6);
    });
  });

  it('decodes the classic precision-5 example and tolerates truncation', () => {
    expect(decodePolyline('_p~iF~ps|U_ulLnnqC_mqNvxq`@', 5)).toEqual([
      [-120.2, 38.5],
      [-120.95, 40.7],
      [-126.453, 43.252],
    ]);
    expect(decodePolyline('_p~iF~ps|U_ulL', 5)).toEqual([[-120.2, 38.5]]);
  });

  it('projects a fix onto the route', () => {
    const p = fx.projection;
    const projection = projectOntoRoute(p.fix, p.route)!;
    expect(projection.segmentIndex).toBe(p.segmentIndex);
    expect(projection.alongM).toBeCloseTo(p.alongM, 6);
    expect(projection.crossTrackM).toBeCloseTo(p.crossTrackM, 6);
  });

  it('estimates an offline trip with the given calibration', () => {
    const e = fx.estimate;
    const route = estimateTrip(e.from, e.to, e.calibration);
    expect(route.distanceM).toBeCloseTo(e.distanceM, 6);
    expect(route.durationS).toBeCloseTo(e.durationS, 6);
    expect(route.source).toBe('estimate');
  });
});

describe('TripEngine (scripted drive parity with Python)', () => {
  it('produces the exact same snapshots as the reference engine', () => {
    const { route, destination, fixes, expected } = fx.drive as {
      route: TripRoute;
      destination: LngLat;
      fixes: { position: LngLat; timestampMs: number; speedMps: number; accuracyM: number }[];
      expected: { remainingM: number; etaS: number; progress: number; offRoute: boolean; shouldReroute: boolean; arrived: boolean }[];
    };
    let now = 0;
    const engine = new TripEngine(route, destination, () => now);
    fixes.forEach((fix, i) => {
      now = fix.timestampMs;
      const snap = engine.update(fix);
      if (snap.shouldReroute) engine.markRerouteRequested();
      const want = expected[i];
      expect(snap.etaS).toBe(want.etaS);
      expect(snap.remainingM).toBeCloseTo(want.remainingM, 2);
      expect(snap.progress).toBeCloseTo(want.progress, 4);
      expect(snap.offRoute).toBe(want.offRoute);
      expect(snap.shouldReroute).toBe(want.shouldReroute);
      expect(snap.arrived).toBe(want.arrived);
    });
  });

  it('keeps reporting arrival once arrived', () => {
    const dest: LngLat = [11.0772, 49.4547];
    const route: TripRoute = { coordinates: [[11.064, 49.448], dest], distanceM: 1200, durationS: 180, source: 'osrm' };
    const engine = new TripEngine(route, dest, () => 0);
    expect(engine.update({ position: dest, timestampMs: 0 }).arrived).toBe(true);
    const later = engine.update({ position: [11.07, 49.45], timestampMs: 5000 });
    expect(later.arrived).toBe(true);
    expect(later.etaS).toBe(0);
  });
});

describe('formatting', () => {
  it('formats ETAs, never showing 0 min before arrival', () => {
    expect(formatEta(0, false)).toBe('Now');
    expect(formatEta(0, true)).toBe('Jetzt');
    expect(formatEta(10, false)).toBe('1 min');
    expect(formatEta(61, false)).toBe('2 min');
    expect(formatEta(3900, false)).toBe('1 h 05 min');
  });

  it('formats distances per locale', () => {
    expect(formatDistance(3, false)).toBe('10 m');
    expect(formatDistance(437, false)).toBe('440 m');
    expect(formatDistance(1450, false)).toBe('1.4 km');
    expect(formatDistance(1450, true)).toBe('1,4 km');
    expect(formatDistance(12_400, false)).toBe('12 km');
  });

  it('computes the shortest heading rotation', () => {
    expect(headingDelta(350, 10)).toBe(20);
    expect(headingDelta(10, 350)).toBe(-20);
  });
});
